#include <stdio.h>
#include <ctype.h>
int main(void) {
    int ch, in_word = 0, count = 0, chars=0;
    while ((ch = getchar()) != EOF) {
        if(!isspace(ch))chars++;
        if (isspace(ch)) in_word = 0;
        else if (!in_word) { ++count; in_word = 1; }
    }
    printf("%d %d\n", count,chars);
    return 0;
}

