#include <stdio.h>
#include <math.h>
int main(void) {
    int ai, bi, ci;
    if (scanf("%d%d%d", &ai, &bi, &ci) != 3) return 1;
    double a=ai, b=bi, c=ci;
    if (a == 0) {
        if (b != 0) printf("ONE %.3f\n", c==0 ? 0.0 : -c/b);
        else puts(c==0 ? "ALL" : "NONE");
    } else {
        double d=b*b-4*a*c, real=-b/(2*a);
        if (d > 0) {
            double u=real-sqrt(d)/(2*a), v=real+sqrt(d)/(2*a);
            if (u>v) { double t=u; u=v; v=t; }
            printf("TWO %.3f %.3f\n", u==0?0.0:u, v==0?0.0:v);
        } else if (d == 0) printf("ONE %.3f\n", real==0?0.0:real);
        else printf("COMPLEX %.3f %.3f\n", real==0?0.0:real, sqrt(-d)/(2*fabs(a)));
    }
    return 0;
}

