#include <stdio.h>
#include <math.h>
int main(void) {
    int t;
    if (scanf("%d", &t)!=1 || t<1 || t>1000) return 1;
    double x=t;
    int ok=0;
    for (int i=0; i<100; ++i) {
        double d=3*x*x;
        if (fabs(d)<1e-14) break;
        double next=x-(x*x*x-t)/d;
        if (fabs(next-x)<1e-10) { x=next; ok=1; break; }
        x=next;
    }
    if (!ok) return 1;
    printf("%.6f\n", x);
    return 0;
}

